#!/bin/bash
# land-monochrome-observatory.sh — astrology's fourth surface: the monochrome
# night. No hue anywhere except the four status meanings; the rail lamp goes
# white with near-black type (a rule change in relief.spec, argued there); the
# hub's relief.css footprint drops to two letterpress lines.
#
# FRONTEND ONLY (together-city-react). Push, and Vercel ships it.
set -euo pipefail

cd "$(dirname "$0")"
[ -d together-city-react ] || { echo "!! Run this from the Together-Ai repo root."; exit 1; }

LOG="$(git log --oneline -40)"
MARK="The observatory opens its curtains"
case "$LOG" in
  *"$MARK"*) ;;
  *) echo "!! This patch applies on top of \"$MARK\" — run land-daylight-observatory.sh first."; exit 1 ;;
esac
NEEDS="The observatory turns the lights off"
case "$LOG" in
  *"$NEEDS"*) echo "== \"$NEEDS\" is already here. Nothing to do."; exit 0 ;;
esac
DIRTY="$(git status --porcelain | grep -Ev '^\?\? (land-.*\.sh|push-.*\.sh|.*\.patch)$' || true)"
if [ -n "$DIRTY" ]; then
  echo "!! Working tree is dirty. Commit or stash first:"; echo "$DIRTY"; exit 1
fi

PATCH="$(mktemp "${TMPDIR:-/tmp}/mono.XXXXXX")"
trap 'rm -f "$PATCH"' EXIT
cat <<'B64EOF' | tr -d '\n' | openssl base64 -d -A > "$PATCH"

B64EOF

WANT="bf763e8d59163ea0f42cbdd47a82ecaea2674ce4d68f97158e1d160fbed9b957"
GOT="$(shasum -a 256 "$PATCH" | awk '{print $1}')"
[ "$GOT" = "$WANT" ] || { echo "!! Patch is corrupt."; echo "   want $WANT"; echo "   got  $GOT"; exit 1; }
echo "== patch verified"
git apply --check -C1 "$PATCH" || { echo "!! Patch does not apply cleanly. Nothing written."; exit 1; }
git am --keep-cr -C1 < "$PATCH"
echo "== committed"

cd together-city-react
npx tsc --noEmit
npx vitest run
npx eslint src || true
node scripts/lint-ceiling.mjs
node scripts/dead-export-audit.mjs
node scripts/motion-ceiling.mjs
node scripts/a11y-audit.mjs
node scripts/nav-audit.mjs
npx vite build
cd ..

echo
echo "==============================================================="
echo " Landed: $NEEDS — push and Vercel ships it."
echo " Astrology is monochrome: near-black ground, no hue but status,"
echo " and a white rail lamp reading 18:1 where the city's reads 3.5."
echo "==============================================================="
